'use strict';
(()=>{const C=window.QuioCore,D=window.QuioDocuments,O=window.QuioOperations,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],app=$('#app');let route='dashboard',listMode='kanban',timerTick=null,pendingImport=null,showArchivedFollowups=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(o,k,d='—')=>esc(o?.[k]||d),biz=id=>C.get('businesses',id),client=id=>C.get('clients',id);
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text||'Sin estado')}</span>`;
const marginBadge=margin=>{const s=C.marginSignal(margin);return`<span class="margin-signal ${s.tone}"><b aria-hidden="true">${s.icon}</b><span><strong>${Number(margin).toFixed(1)}%</strong><small>${s.label}</small></span></span>`};
const empty=(title='Aún no hay datos suficientes.',text='Crea el primer registro para comenzar.')=>`<div class="empty"><strong>${title}</strong><span>${text}</span></div>`;
function toast(message){
  const el=$('#toast'),openDialogs=$$('dialog[open]'),host=openDialogs.at(-1)||document.body;
  host.appendChild(el);
  el.textContent=message;el.classList.add('show');clearTimeout(el.t);
  el.t=setTimeout(()=>el.classList.remove('show'),Math.max(2800,Math.min(6500,String(message).length*55)));
}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h2>${title}</h2><p>${desc}</p></div><div class="toolbar no-print">${actions}</div></div>`}
function metric(label,value,note='',cls=''){return `<article class="metric ${cls}"><span>${label}</span><strong>${value}</strong>${note?`<small>${note}</small>`:''}</article>`}
function active(items){return items.filter(x=>!x.archived)}
function render(){
  const redirects={prospects:'clients',followups:'clients',packages:'settings',documents:'projects',time:'projects',inventory:'settings'};
  route=(location.hash||'#dashboard').slice(1);route=redirects[route]||route;
  if(!['dashboard','clients','reviews','quotes','projects','finance','settings'].includes(route))route='dashboard';
  if(location.hash!==`#${route}`)history.replaceState(null,'',`#${route}`);
  $$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));const titles={dashboard:'Resumen',clients:'Clientes',reviews:'Revisiones Quio',quotes:'Cotizaciones',projects:'Proyectos',finance:'Finanzas',settings:'Configuración'};$('#pageTitle').textContent=titles[route];
  ({dashboard:()=>O.renderDashboard(app),clients:()=>O.renderClients(app),reviews:renderReviews,quotes:renderQuotes,projects:()=>O.renderProjects(app),finance:()=>O.renderFinance(app),settings:()=>O.renderSettings(app)}[route])();
  D.enhance(route,app);bindActions();app.focus({preventScroll:true});
}
function renderDashboard(){
  const x=C.calculations(),today=new Date().toISOString().slice(0,10),soon=new Date(Date.now()+7*86400000).toISOString().slice(0,10);
  const upcoming=C.list('followups').filter(f=>f.status==='Pendiente'&&f.date<=soon),low=C.list('inventoryProducts').filter(p=>Number(p.stock)<=Number(p.minStock)),projects=C.list('projects').filter(p=>!['Cerrado','Cancelado'].includes(p.status));
  const alerts=[...upcoming.filter(f=>f.date<today).map(f=>({t:'Seguimiento vencido',d:f.reason||'Contacto pendiente',r:'followups',tone:'red',icon:'!'})),...low.map(p=>({t:'Inventario bajo',d:`${p.name}: ${p.stock} disponibles`,r:'inventory',tone:'amber',icon:'▦'})),...C.list('payments').filter(p=>p.status==='Pendiente'&&p.expectedDate<today).map(p=>({t:'Pago vencido',d:C.money(p.amount),r:'finance',tone:'red',icon:'$'}))];
  app.innerHTML=`<section class="page">${pageHead('Hola, esto es lo importante hoy','Aquí puedes ver qué va bien y qué conviene atender después.','<button class="btn" data-action="seed">Ver datos de ejemplo</button>')}
  <div class="metrics">${metric('Prospectos activos',C.list('prospects').filter(p=>!['Ganado','No continuó'].includes(p.stage)).length)}${metric('Clientes activos',C.list('clients').filter(c=>c.status==='Activo').length)}${metric('Revisiones realizadas',C.list('reviews').length)}${metric('Cotizaciones pendientes',C.list('quotes').filter(q=>['Enviada','Borrador'].includes(q.status)).length)}${metric('Proyectos en curso',projects.length)}${metric('Pagos pendientes',C.money(x.receivable),'Cuentas por cobrar',x.receivable?'attention':'')}</div>
  <div class="metrics">${metric('Cobrado este mes',C.money(x.incomeNet),'Ingreso Quio sin impuestos')}${metric('Pendiente por cobrar',C.money(x.receivable))}${metric('Gastos pagados',C.money(x.spent))}${metric('Flujo real',C.money(x.net),'Cobrado − pagado')}${metric('Horas invertidas',x.hours.toFixed(1)+' h')}${metric('Valor efectivo/hora',x.hours?C.money(x.effectiveHourly):'Sin datos')}</div>
  <div class="metrics">${metric('Utilidad estimada',C.money(x.estimatedProfit),'Costo económico incluido')}${metric('Utilidad económica real',C.money(x.actualProfit),'No es flujo disponible')}${metric('Margen promedio',x.marginAverage?`${x.marginAverage.toFixed(1)}%`:'Sin datos')}${metric('Proyectos saludables',x.greenProjects,'Margen verde')}${metric('Margen ajustado',x.amberProjects,'Proyectos amarillos')}${metric('Rentabilidad crítica',x.redProjects,'Proyectos rojos',x.redProjects?'attention':'')}</div>
  <div class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h3>Meta Quio mensual</h3><p>${C.money(x.incomeNet)} cobrados de ${C.money(x.goal)}</p></div><strong>${Math.round(x.goalPct)}%</strong></div><div class="progress"><i style="width:${x.goalPct}%"></i></div><div class="personal-goal"><span>Meta personal total</span><strong>${C.money(x.totalPersonalIncome)} de ${C.money(x.totalGoal)}</strong><small>Empleo actual + ingreso Quio cobrado; el sueldo no se registra como venta.</small><div class="progress"><i style="width:${x.totalGoalPct}%"></i></div></div></article><article class="panel attention-panel"><div class="panel-head"><div><h3><span class="attention-spark" aria-hidden="true">✦</span> Alertas</h3><p>Elementos que conviene resolver</p></div><span class="attention-count">${alerts.length}</span></div>${alerts.length?`<div class="alert-list">${alerts.slice(0,6).map(a=>`<a class="alert-row ${a.tone}" href="#${a.r}"><span class="alert-icon" aria-hidden="true">${a.icon}</span><div><strong>${a.t}</strong><small>${esc(a.d)}</small></div><span class="alert-arrow">→</span></a>`).join('')}</div>`:empty('Todo está al día','No hay alertas activas.')}</article>
  <article class="panel"><div class="panel-head"><div><h3>Proyectos activos</h3><p>Avance y próximo paso</p></div><a href="#projects">Ver todos</a></div>${projects.length?`<div class="list">${projects.slice(0,5).map(p=>`<div class="list-row"><div><strong>${esc(p.name)}</strong><small>${esc(p.nextStep||'Sin próximo paso')}</small></div><div>${badge(p.status)}</div><div><div class="progress"><i style="width:${Number(p.progress)||0}%"></i></div></div><div>${p.progress||0}%</div></div>`).join('')}</div>`:empty()}</article>
  <article class="panel"><div class="panel-head"><div><h3>Próximos seguimientos</h3><p>Vencidos y siguientes 7 días</p></div><a href="#followups">Ver todos</a></div>${upcoming.length?upcoming.slice(0,6).map(f=>`<div class="list-row"><div><strong>${esc(f.reason)}</strong><small>${C.date(f.date)} · ${esc(f.channel||'Sin canal')}</small></div>${badge(f.date<today?'Vencido':'Próximo',f.date<today?'red':'amber')}</div>`).join(''):empty()}</article></div></section>`;
}
function renderProspects(){
 const arr=C.list('prospects'),stages=C.db().settings.prospectStages||[];app.innerHTML=`<section class="page">${pageHead('Prospectos','Da seguimiento desde el primer contacto hasta la decisión.','<button class="btn primary" data-new="prospect">+ Prospecto</button>')}<div class="tabs"><button class="${listMode==='kanban'?'active':''}" data-mode="kanban">Tablero</button><button class="${listMode==='list'?'active':''}" data-mode="list">Lista</button></div>${listMode==='kanban'?`<div class="kanban">${stages.map(s=>`<section class="kanban-col"><h3>${s}<span>${arr.filter(p=>p.stage===s).length}</span></h3>${arr.filter(p=>p.stage===s).map(p=>`<article class="kanban-card"><strong>${esc(p.businessName)}</strong><p>${esc(p.contactName||'Sin contacto')} · ${esc(p.industry||'Giro sin registrar')}</p><small>${p.nextFollowup?'Próximo: '+C.date(p.nextFollowup):'Sin seguimiento'}</small><select data-stage="${p.id}" aria-label="Cambiar etapa">${stages.map(x=>`<option ${x===p.stage?'selected':''}>${x}</option>`).join('')}</select><div class="row-actions"><button class="btn small" data-edit="prospects:${p.id}">Editar</button>${p.stage==='Ganado'?`<button class="btn small primary" data-convert="${p.id}">Convertir</button>`:''}</div></article>`).join('')}</section>`).join('')}</div>`:renderList(arr,'prospects',p=>[p.businessName,p.contactName,p.stage,p.nextFollowup?C.date(p.nextFollowup):'—'])}</section>`;
}
function renderClients(){const clients=C.list('clients'),businesses=C.list('businesses');app.innerHTML=`<section class="page">${pageHead('Clientes y negocios','Una persona puede estar asociada a varios negocios.','<button class="btn" data-new="business">+ Negocio</button><button class="btn primary" data-new="client">+ Cliente</button>')}<div class="dashboard-grid"><article class="panel"><div class="panel-head"><h3>Clientes</h3></div>${clients.length?clients.map(c=>`<div class="list-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.email||'Sin correo')} · ${esc(c.phone||'Sin teléfono')}</small></div>${badge(c.status)}<div>${(c.businessIds||[]).length} negocio(s)</div><div class="row-actions"><button class="btn small" data-edit="clients:${c.id}">Editar</button><button class="btn small" data-archive="clients:${c.id}">Archivar</button></div></div>`).join(''):empty()}</article><article class="panel"><div class="panel-head"><h3>Negocios</h3></div>${businesses.length?businesses.map(b=>`<div class="list-row"><div><strong>${esc(b.name)}</strong><small>${esc(b.industry||'Giro sin registrar')} · ${esc(b.city||'Sin ciudad')}</small></div>${badge(b.status)}<div>${C.list('reviews').filter(r=>r.businessId===b.id).length} revisión(es)</div><div class="row-actions"><button class="btn small" data-edit="businesses:${b.id}">Editar</button><button class="btn small" data-archive="businesses:${b.id}">Archivar</button></div></div>`).join(''):empty()}</article></div></section>`}
function renderReviews(){const arr=C.list('reviews');app.innerHTML=`<section class="page">${pageHead('Revisiones Quio','Las revisiones terminadas se sincronizan automáticamente; la importación JSON queda disponible como respaldo.','<button class="btn" data-action="import-review">Importar respaldo JSON</button><a class="btn primary btn-primary" href="../revisiones/">+ Revisión</a>')}<div class="alert"><strong>IQPD</strong> significa Índice Quio de Presencia Digital. El sistema no reconstruye ni modifica la metodología del diagnóstico.</div><article class="panel">${arr.length?arr.map(r=>{const b=biz(r.businessId);return`<div class="list-row"><div><strong>${esc(b?.name||r.original?.business?.name||'Negocio sin asociar')}</strong><small>${C.date(r.reviewDate)} · Esquema ${esc(r.sourceSchemaVersion||'18.0')}</small></div><div><span class="score">${r.iqpd}</span>/100</div><div>${badge(r.level)}</div><div class="row-actions"><button class="btn small" data-review="${r.id}">Ver</button><button class="btn small" data-download-review="${r.id}">JSON</button></div></div>`}).join(''):empty('Aún no hay revisiones sincronizadas','Abre Revisiones Quio para crear la primera.')}</article>${arr.length>=2?`<article class="panel" style="margin-top:16px"><div class="panel-head"><div><h3>Comparar revisiones</h3><p>Selecciona dos revisiones del mismo negocio.</p></div></div><div class="toolbar"><select id="compareA">${arr.map(r=>`<option value="${r.id}">${esc(biz(r.businessId)?.name||r.original?.business?.name||'Negocio')} · ${C.date(r.reviewDate)} · ${r.iqpd}</option>`).join('')}</select><select id="compareB">${arr.map((r,i)=>`<option value="${r.id}" ${i===1?'selected':''}>${esc(biz(r.businessId)?.name||r.original?.business?.name||'Negocio')} · ${C.date(r.reviewDate)} · ${r.iqpd}</option>`).join('')}</select><button class="btn" data-action="compare">Comparar</button></div><div id="comparison"></div></article>`:''}</section>`}
function renderPackages(){
 const packages=C.list('packages').sort((a,b)=>a.order-b.order),first=packages[0],defaults=first||{price:0,estimatedHours:0,stands:0,nfcCards:0,trips:0};
 app.innerHTML=`<section class="page">${pageHead('Paquetes y costeo','Decide precios con el costo completo de tu tiempo, materiales y desembolsos.','<button class="btn primary" data-new="package">+ Paquete</button>')}
 <div class="package-grid">${packages.map(pkg=>{const c=C.packageCost(pkg);return`<article class="panel package-card"><div class="package-top"><div><p class="eyebrow">PAQUETE QUIO</p><h3>${esc(pkg.name)}</h3></div><button class="btn small" data-edit="packages:${pkg.id}">Editar</button></div><strong class="package-price">${C.money(c.netPrice)}</strong><p>${c.hours} h estimadas · ${Number(pkg.stands||0)+Number(pkg.nfcCards||0)} NFC · ${pkg.trips} traslado</p>${marginBadge(c.margin)}<div class="cost-stack"><span><small>Mano de obra</small><b>${C.money(c.labor)}</b></span><span><small>Costos directos</small><b>${C.money(c.directCost)}</b></span><span><small>Costo económico</small><b>${C.money(c.economicCost)}</b></span><span><small>Utilidad estimada</small><b>${C.money(c.profit)}</b></span></div><details><summary>Qué incluye</summary><ul>${(pkg.contents||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${pkg.note?`<p class="helper">${esc(pkg.note)}</p>`:''}</details><button class="btn primary full-btn" data-quote-package="${pkg.id}">Crear cotización</button></article>`}).join('')}</div>
 <div class="finance-tools"><article class="panel simulator-panel"><div class="panel-head"><div><p class="eyebrow">SIMULADOR</p><h3>Prueba un precio antes de ofrecerlo</h3><p>Los impuestos se calculan después y no inflan el margen.</p></div></div><div class="simulator-layout"><div class="form-grid compact-fields">${field('simPrice','Precio de venta',defaults.price,'number')}${field('simDiscount','Descuento',0,'number')}${field('simHours','Horas estimadas',defaults.estimatedHours,'number')}${field('simHourly','Valor por hora',C.db().settings.hourlyTarget,'number')}${field('simStands','Unidades NFC',defaults.stands,'number')}${field('simCards','NFC adicional',defaults.nfcCards,'number')}${field('simTrips','Traslados',defaults.trips,'number')}${field('simSoftware','Software',0,'number')}${field('simProviders','Proveedores',0,'number')}${field('simOther','Otros costos',0,'number')}${field('simTax','Impuestos (%)',C.db().settings.taxRate,'number')}</div><div id="simResults" class="sim-results"></div></div></article>
 <article class="panel projection-panel"><div class="panel-head"><div><p class="eyebrow">ESCENARIOS, NO PRONÓSTICOS</p><h3>¿Qué exigiría atender esta mezcla?</h3><p>Úsalo para detectar cuándo estandarizar, automatizar o delegar.</p></div></div><div class="scenario-buttons"><button class="btn small" data-scenario="10">10 clientes</button><button class="btn small" data-scenario="100">100 clientes</button><button class="btn small" data-scenario="1000">1,000 clientes</button></div><div class="projection-inputs">${packages.map(pkg=>field(`mix_${pkg.id}`,pkg.name,0,'number')).join('')}</div><div id="projectionResults"></div></article></div></section>`;
 updateSimulator();updateProjection();
}
function formNumber(name){return Number($(`#f_${name}`)?.value)||0}
function updateSimulator(){
 const target=$('#simResults');if(!target)return;
 const result=C.estimate({price:formNumber('simPrice'),discount:formNumber('simDiscount'),estimatedHours:formNumber('simHours'),hourlyValue:formNumber('simHourly'),stands:formNumber('simStands'),nfcCards:formNumber('simCards'),trips:formNumber('simTrips'),software:formNumber('simSoftware'),providers:formNumber('simProviders'),otherCosts:formNumber('simOther'),taxRate:formNumber('simTax')});
 target.innerHTML=`${marginBadge(result.margin)}<div class="cost-stack result-stack"><span><small>Precio sin impuestos</small><b>${C.money(result.netPrice)}</b></span><span><small>Impuestos</small><b>${C.money(result.taxes)}</b></span><span><small>Total al cliente</small><b>${C.money(result.total)}</b></span><span><small>Mano de obra</small><b>${C.money(result.labor)}</b></span><span><small>Costos directos</small><b>${C.money(result.directCost)}</b></span><span><small>Costo económico</small><b>${C.money(result.economicCost)}</b></span><span><small>Utilidad</small><b>${C.money(result.profit)}</b></span><span><small>Horas máximas al ${C.db().settings.healthyMargin}%</small><b>${result.maxHours.toFixed(1)} h</b></span></div><div class="minimum-prices"><span>Precio mínimo 45% <b>${C.money(result.minPrice45)}</b></span><span>Precio mínimo 55% <b>${C.money(result.minPrice55)}</b></span><span>Precio mínimo 60% <b>${C.money(result.minPrice60)}</b></span></div>`;
}
function updateProjection(){
 const target=$('#projectionResults');if(!target)return;const mix={};C.list('packages').forEach(pkg=>mix[pkg.id]=formNumber(`mix_${pkg.id}`));const p=C.projection(mix);
 target.innerHTML=`${p.overCapacity?'<div class="capacity-warning"><strong>Capacidad superada.</strong><span>Este escenario requeriría estandarización, automatización, delegación, proveedores o personal.</span></div>':''}<div class="cost-stack projection-results"><span><small>Proyectos</small><b>${p.projects}</b></span><span><small>Ingreso</small><b>${C.money(p.revenue)}</b></span><span><small>Horas necesarias</small><b>${p.hours.toFixed(1)} h</b></span><span><small>Capacidad configurada</small><b>${p.capacity.toFixed(1)} h</b></span><span><small>Costos directos</small><b>${C.money(p.directCost)}</b></span><span><small>Costo económico</small><b>${C.money(p.economicCost)}</b></span><span><small>Utilidad estimada</small><b>${C.money(p.profit)}</b></span><span><small>Margen</small><b>${p.margin.toFixed(1)}%</b></span><span><small>Traslados</small><b>${p.trips}</b></span><span><small>NFC</small><b>${p.stands+p.nfcCards}</b></span></div>`;
}
function renderQuotes(){D.renderQuotes(app)}
function renderProjects(){const arr=C.list('projects');app.innerHTML=`<section class="page">${pageHead('Proyectos','Compara lo previsto con el costo económico y resultado real.','<button class="btn primary" data-new="project">+ Proyecto</button>')}<article class="panel">${arr.length?arr.map(p=>{const x=C.projectEconomics(p.id);return`<div class="list-row finance-row"><div><strong>${esc(p.name)}</strong><small>${esc(biz(p.businessId)?.name||'Sin negocio')} · Compromiso ${C.date(p.dueDate)}</small></div><div>${badge(p.status)}<small>${p.progress||0}% de avance</small></div><div><strong>${C.money(x.actualProfit)}</strong><small>utilidad económica real</small></div><div>${marginBadge(x.actualMargin)}</div><div><strong>${x.actualHours.toFixed(1)} h</strong><small>${x.hourDeviation>=0?'+':''}${x.hourDeviation.toFixed(1)} h vs. previsto</small></div><div class="row-actions"><button class="btn small" data-project="${p.id}">Ver rentabilidad</button><button class="btn small" data-edit="projects:${p.id}">Editar</button></div></div>`}).join(''):empty()}</article></section>`}
function renderFinance(){const x=C.calculations(),payments=C.list('payments'),expenses=C.list('expenses');app.innerHTML=`<section class="page">${pageHead('Finanzas','Separa ingreso, costo económico, utilidad y dinero disponible.','<button class="btn" data-new="expense">+ Gasto</button><button class="btn primary" data-new="payment">+ Pago</button>')}<div class="metrics">${metric('Cobrado sin impuestos',C.money(x.incomeNet),'Este mes')}${metric('Pendiente',C.money(x.receivable),'Por cobrar')}${metric('Gastos pagados',C.money(x.spent),'Salida real')}${metric('Flujo real',C.money(x.net),'Cobrado bruto − pagado')}${metric('Utilidad económica real',C.money(x.actualProfit),'Incluye costo del tiempo')}${metric('Margen promedio',x.marginAverage?`${x.marginAverage.toFixed(1)}%`:'Sin datos')}</div><div class="metrics">${metric('Ticket promedio',x.averageTicket?C.money(x.averageTicket):'Sin datos')}${metric('Valor efectivo/h',x.hours?C.money(x.effectiveHourly):'Sin datos')}${metric('Paquetes vendidos',x.packagesSold)}${metric('Proyectos verdes',x.greenProjects)}${metric('Proyectos amarillos',x.amberProjects)}${metric('Proyectos rojos',x.redProjects,'',x.redProjects?'attention':'')}</div><div class="dashboard-grid"><article class="panel"><div class="panel-head"><h3>Ingresos y pagos</h3></div>${payments.length?payments.map(p=>`<div class="list-row"><div><strong>${esc(p.type||'Pago')}</strong><small>${esc(client(p.clientId)?.name||'Sin cliente')} · ${C.date(p.actualDate||p.expectedDate)}</small></div><div><strong>${C.money(p.amount)}</strong><small>${p.includesTax?'incluye impuestos':'sin impuestos registrados'}</small></div>${badge(p.status,p.status==='Cobrado'?'green':'amber')}<div class="row-actions"><button class="btn small" data-edit="payments:${p.id}">Editar</button></div></div>`).join(''):empty()}</article><article class="panel"><div class="panel-head"><h3>Gastos</h3></div>${expenses.length?expenses.map(e=>`<div class="list-row"><div><strong>${esc(e.category)}</strong><small>${esc(e.notes||'Sin notas')} · ${C.date(e.date)}</small></div><div>${C.money(e.amount)}</div><div>${esc(C.get('projects',e.projectId)?.name||'General')}</div><div class="row-actions"><button class="btn small" data-edit="expenses:${e.id}">Editar</button></div></div>`).join(''):empty()}</article></div></section>`}
function timerState(){try{return JSON.parse(localStorage.getItem('quio_timer_v1')||'null')}catch{return null}}
function timerSeconds(){const t=timerState();if(!t)return 0;return Number(t.elapsed||0)+(t.running?Math.floor((Date.now()-t.startedAt)/1000):0)}
function fmtTimer(s){return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')}
function renderTime(){const entries=C.list('timeEntries'),t=timerState();app.innerHTML=`<section class="page">${pageHead('Control de tiempo','El cronómetro conserva su estado aunque cierres o recargues la página.','<button class="btn" data-new="time">+ Registro manual</button>')}<div class="timer"><div><small>CRONÓMETRO</small><strong id="timerValue">${fmtTimer(timerSeconds())}</strong><p>${esc(t?.description||'Sin descripción')}</p></div><div class="timer-actions">${!t?.running?'<button class="btn primary" data-timer="start">Iniciar</button>':'<button class="btn" data-timer="pause">Pausar</button>'}<button class="btn" data-timer="stop" ${!t?'disabled':''}>Detener y guardar</button></div></div><div class="metrics">${metric('Esta semana',`${(entries.filter(e=>new Date(e.date)>=new Date(Date.now()-7*86400000)).reduce((s,e)=>s+Number(e.minutes||0),0)/60).toFixed(1)} h`)}${metric('Este mes',`${C.calculations().hours.toFixed(1)} h`)}${metric('Valor objetivo/h',C.money(C.db().settings.hourlyTarget))}${metric('Valor efectivo/h',C.calculations().hours?C.money(C.calculations().effectiveHourly):'Sin datos')}</div><article class="panel">${entries.length?entries.map(e=>`<div class="list-row"><div><strong>${esc(e.description||'Trabajo sin descripción')}</strong><small>${C.date(e.date)} · ${esc(C.get('projects',e.projectId)?.name||'Sin proyecto')}</small></div><div>${(Number(e.minutes)/60).toFixed(2)} h</div><div>${C.money(e.hourlyRate||C.db().settings.hourlyTarget)}/h</div><div class="row-actions"><button class="btn small" data-edit="timeEntries:${e.id}">Editar</button></div></div>`).join(''):empty()}</article></section>`;clearInterval(timerTick);timerTick=setInterval(()=>{const el=$('#timerValue');if(el)el.textContent=fmtTimer(timerSeconds())},1000)}
function renderInventory(){const arr=C.list('inventoryProducts'),moves=C.list('inventoryMovements');app.innerHTML=`<section class="page">${pageHead('Inventario','Controla entradas, salidas, ajustes y materiales asignados.','<button class="btn" data-new="movement">+ Movimiento</button><button class="btn primary" data-new="product">+ Producto</button>')}<article class="panel">${arr.length?arr.map(p=>`<div class="list-row"><div><strong>${esc(p.name)}</strong><small>${esc(p.sku||'Sin SKU')} · ${esc(p.category)}</small></div><div><strong>${p.stock}</strong><small>mínimo ${p.minStock||0}</small></div><div>${C.money(p.unitCost)}</div><div>${Number(p.stock)<=Number(p.minStock)?badge('Existencia baja','red'):badge('Disponible','green')}</div><div class="row-actions"><button class="btn small" data-edit="inventoryProducts:${p.id}">Editar</button></div></div>`).join(''):empty()}</article><article class="panel" style="margin-top:16px"><div class="panel-head"><h3>Últimos movimientos</h3></div>${moves.length?moves.slice(0,10).map(m=>`<div class="list-row"><div><strong>${esc(C.get('inventoryProducts',m.productId)?.name||'Producto')}</strong><small>${C.date(m.date)} · ${esc(m.notes||'')}</small></div><div>${esc(m.type)}</div><div>${m.quantity>0?'+':''}${m.quantity}</div><div>${esc(C.get('projects',m.projectId)?.name||'')}</div></div>`).join(''):empty()}</article></section>`}
function renderFollowups(){const arr=C.list('followups',{includeArchived:showArchivedFollowups}).filter(f=>showArchivedFollowups?f.archived:!f.archived).sort((a,b)=>String(a.date).localeCompare(String(b.date))),today=new Date().toISOString().slice(0,10),archivedCount=C.list('followups',{includeArchived:true}).filter(f=>f.archived).length;app.innerHTML=`<section class="page">${pageHead(showArchivedFollowups?'Seguimientos archivados':'Seguimientos',showArchivedFollowups?'Consulta y restaura seguimientos que ya no están activos.':'Mantén claro quién requiere contacto, por qué y cuándo.',`<button class="btn" data-toggle-followup-archive>${showArchivedFollowups?'← Ver activos':`Ver archivados${archivedCount?` (${archivedCount})`:''}`}</button>${showArchivedFollowups?'':'<button class="btn primary" data-new="followup">+ Seguimiento</button>'}`)}<article class="panel">${arr.length?arr.map(f=>`<div class="list-row"><div><strong>${esc(f.reason)}</strong><small>${esc(f.channel||'Sin canal')} · ${esc(f.notes||'Sin notas')}</small></div><div>${C.date(f.date)}</div><div>${badge(f.archived?'Archivado':f.status,f.archived?'':f.status==='Realizado'?'green':f.date<today?'red':'amber')}</div><div>${esc(client(f.clientId)?.name||C.get('prospects',f.prospectId)?.businessName||C.get('projects',f.projectId)?.name||'Sin relación')}</div><div class="row-actions">${f.archived?`<button class="btn small" data-restore-followup="${f.id}">Restaurar</button>`:`${f.status!=='Realizado'?`<button class="btn small" data-done-followup="${f.id}">Realizado</button>`:''}<button class="btn small" data-edit="followups:${f.id}">Editar</button><button class="btn small" data-archive="followups:${f.id}">Archivar</button>`}</div></div>`).join(''):empty(showArchivedFollowups?'No hay seguimientos archivados.':'Aún no hay seguimientos.','')}</article></section>`}
function renderSettings(){const s=C.db().settings;app.innerHTML=`<section class="page">${pageHead('Configuración','Todos estos valores recalculan paquetes, simuladores y nuevas cotizaciones.')}<div class="dashboard-grid"><form class="panel" id="settingsForm"><div class="panel-head"><div><h3>Modelo económico de Quio</h3><p>El tiempo del fundador siempre se reconoce como costo.</p></div></div><div class="form-grid">${field('companyName','Nombre de la empresa',s.companyName)}${field('currency','Moneda',s.currency)}${field('monthlyGoal','Meta mensual Quio',s.monthlyGoal,'number')}${field('annualGoal','Meta anual Quio',s.annualGoal,'number')}${field('founderEmploymentIncome','Ingreso mensual actual por empleo',s.founderEmploymentIncome,'number')}${field('totalMonthlyIncomeGoal','Meta mensual personal total',s.totalMonthlyIncomeGoal,'number')}${field('hourlyTarget','Valor económico por hora',s.hourlyTarget,'number')}${field('standUnitCost','Costo unitario NFC',s.standUnitCost,'number')}${field('nfcCardUnitCost','Costo NFC adicional',s.nfcCardUnitCost,'number')}${field('averageTripCost','Traslado promedio por proyecto',s.averageTripCost,'number')}${field('healthyMargin','Margen saludable objetivo (%)',s.healthyMargin,'number')}${field('warningMargin','Umbral mínimo amarillo (%)',s.warningMargin,'number')}${field('monthlyCapacityHours','Capacidad mensual del fundador (h)',s.monthlyCapacityHours,'number')}${field('taxRate','Impuesto predeterminado (%)',s.taxRate,'number')}${selectField('effectiveHourlyBasis','Valor efectivo por hora basado en',['income','profit'].map(x=>({value:x,label:x==='income'?'Ingreso reconocido':'Utilidad económica'})),s.effectiveHourlyBasis)}</div><div class="dialog-actions"><button class="btn primary" type="submit">Guardar y recalcular</button></div></form><article class="panel"><div class="panel-head"><div><h3>Paquetes configurables</h3><p>Nombres, precios, horas, materiales, traslados y contenidos.</p></div></div><a class="btn primary" href="#packages">Abrir paquetes y simuladores</a></article><article class="panel"><div class="panel-head"><div><h3>Respaldo e intercambio</h3><p>El archivo incluye fecha y versión del esquema. v9 conserva compatibilidad razonable con respaldos anteriores.</p></div></div><div class="toolbar"><button class="btn" data-action="backup">Exportar respaldo</button><button class="btn" data-action="restore">Restaurar</button><button class="btn" data-action="merge">Fusionar</button><button class="btn" data-action="csv">Exportar CSV</button></div>${C.db().meta?.preV9BackupKey?'<p class="helper">Se creó automáticamente una copia local previa a la migración v9.</p>':C.db().meta?.preV8BackupKey?'<p class="helper">Se conserva la copia local previa a la migración v8.</p>':''}</article><article class="panel"><div class="panel-head"><div><h3>Servicios y soluciones</h3><p>Valores base editables para cotizaciones personalizadas.</p></div></div>${C.list('services').map(x=>`<div class="list-row"><div><strong>${esc(x.name)}</strong></div><div>${C.money(x.basePrice)}</div><div>${C.money(x.directCost)} costo directo</div><button class="btn small" data-edit="services:${x.id}">Editar</button></div>`).join('')}</article><article class="panel danger-zone"><div class="panel-head"><div><h3>Zona de seguridad</h3><p>Estas acciones están separadas de las tareas cotidianas.</p></div></div><div class="toolbar"><button class="btn" data-action="seed">Restablecer ejemplos</button><button class="btn danger" data-action="reset">Eliminar todos los datos</button></div></article></div></section>`}
function field(name,label,value='',type='text',full=false,attrs=''){return `<div class="field ${full?'full':''}"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function selectField(name,label,options,value='',full=false){return `<div class="field ${full?'full':''}"><label for="f_${name}">${label}</label><select id="f_${name}" name="${name}">${options.map(x=>`<option value="${esc(x.value??x)}" ${(x.value??x)===value?'selected':''}>${esc(x.label??x)}</option>`).join('')}</select></div>`}
function textarea(name,label,value='',full=true){return `<div class="field ${full?'full':''}"><label for="f_${name}">${label}</label><textarea id="f_${name}" name="${name}" rows="3">${esc(value)}</textarea></div>`}
function renderList(arr,entity,map){return `<article class="panel">${arr.length?arr.map(x=>{const m=map(x);return`<div class="list-row"><div><strong>${esc(m[0])}</strong><small>${esc(m[1])}</small></div><div>${esc(m[2])}</div><div>${esc(m[3])}</div><div class="row-actions"><button class="btn small" data-edit="${entity}:${x.id}">Editar</button><button class="btn small" data-archive="${entity}:${x.id}">Archivar</button></div></div>`}).join(''):empty()}</article>`}
function options(entity,label='name'){return[{value:'',label:'Sin asociar'},...C.list(entity).map(x=>({value:x.id,label:x[label]||x.businessName||x.id}))]}
function openForm(kind,record=null){
 document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());
 const forms={
 prospect:{entity:'prospects',title:'Prospecto',html:()=>field('businessName','Nombre comercial',record?.businessName,'text',true,'required')+field('contactName','Contacto',record?.contactName)+field('industry','Giro explícito',record?.industry)+field('phone','Teléfono',record?.phone,'tel')+field('email','Correo',record?.email,'email')+selectField('stage','Etapa',C.db().settings.prospectStages,record?.stage||'Nuevo')+field('lastContact','Último contacto',record?.lastContact,'date')+field('nextFollowup','Próximo seguimiento',record?.nextFollowup,'date')+textarea('notes','Notas',record?.notes)},
 client:{entity:'clients',title:'Cliente',html:()=>field('name','Nombre completo',record?.name,'text',true,'required')+field('phone','Teléfono',record?.phone,'tel')+field('email','Correo',record?.email,'email')+selectField('preferredContact','Contacto preferido',['WhatsApp','Llamada','Correo','Otro'],record?.preferredContact)+selectField('status','Estatus',['Activo','Inactivo','Potencial'],record?.status||'Activo')+textarea('notes','Notas',record?.notes)},
 business:{entity:'businesses',title:'Negocio',html:()=>field('name','Nombre comercial',record?.name,'text',true,'required')+field('industry','Giro explícito',record?.industry,'text',false,'required')+field('phone','Teléfono',record?.phone,'tel')+field('email','Correo',record?.email,'email')+field('address','Dirección',record?.address,'text',true)+field('city','Ciudad',record?.city)+field('state','Estado',record?.state||'Sonora')+field('mapsUrl','URL de Google Maps',record?.mapsUrl,'url')+field('websiteUrl','Sitio web',record?.websiteUrl,'url')+selectField('status','Estatus',['Activo','Inactivo','Potencial'],record?.status||'Activo')+textarea('notes','Notas',record?.notes)},
 package:{entity:'packages',title:'Paquete',html:()=>field('name','Nombre del paquete',record?.name,'text',true,'required')+field('price','Precio sin impuestos',record?.price||0,'number')+field('estimatedHours','Horas estimadas',record?.estimatedHours||0,'number')+field('stands','Unidades NFC',record?.stands||0,'number')+field('nfcCards','NFC adicional',record?.nfcCards||0,'number')+field('trips','Número de traslados',record?.trips||0,'number')+field('software','Software',record?.software||0,'number')+field('providers','Proveedores',record?.providers||0,'number')+field('otherCosts','Otros costos',record?.otherCosts||0,'number')+textarea('contentsText','Contenido, un elemento por línea',(record?.contents||[]).join('\n'))+textarea('note','Nota',record?.note)},
 quote:{entity:'quotes',title:'Cotización',html:()=>D.quoteForm(record||{})},
 project:{entity:'projects',title:'Proyecto',html:()=>field('name','Nombre del proyecto',record?.name,'text',true,'required')+selectField('clientId','Cliente',options('clients'),record?.clientId)+selectField('businessId','Negocio',options('businesses'),record?.businessId)+selectField('status','Estado',C.db().settings.projectStatuses,record?.status||'Por iniciar')+field('startDate','Inicio',record?.startDate,'date')+field('dueDate','Fecha compromiso',record?.dueDate,'date')+field('progress','Avance (%)',record?.progress||0,'number')+field('nextStep','Próximo paso',record?.nextStep)+textarea('notes','Notas',record?.notes)},
 payment:{entity:'payments',title:'Pago',html:()=>selectField('clientId','Cliente',options('clients'),record?.clientId)+selectField('projectId','Proyecto',options('projects'),record?.projectId)+selectField('type','Tipo',['Ingreso','Anticipo','Pago parcial','Saldo'],record?.type||'Ingreso')+field('amount','Importe',record?.amount||0,'number',false,'required min="0" step="0.01"')+selectField('includesTax','¿El importe incluye impuestos?',[{value:'false',label:'No, es ingreso sin impuestos'},{value:'true',label:'Sí, incluye impuestos'}],String(record?.includesTax||false))+field('taxRate','Tasa de impuesto (%)',record?.taxRate??C.db().settings.taxRate,'number')+selectField('status','Estado',['Pendiente','Cobrado','Cancelado'],record?.status||'Pendiente')+field('expectedDate','Fecha prevista',record?.expectedDate,'date')+field('actualDate','Fecha real',record?.actualDate,'date')+selectField('method','Método',['Transferencia','Efectivo','Tarjeta','Otro'],record?.method)+textarea('notes','Notas',record?.notes)},
 expense:{entity:'expenses',title:'Gasto',html:()=>selectField('projectId','Proyecto',options('projects'),record?.projectId)+selectField('category','Categoría',C.db().settings.expenseCategories,record?.category)+field('amount','Importe',record?.amount||0,'number',false,'required min="0" step="0.01"')+selectField('status','Estado',['Pagado','Pendiente'],record?.status||'Pagado')+field('date','Fecha',record?.date||new Date().toISOString().slice(0,10),'date')+textarea('notes','Notas',record?.notes)},
 time:{entity:'timeEntries',title:'Registro de tiempo',html:()=>selectField('projectId','Proyecto',options('projects'),record?.projectId)+selectField('clientId','Cliente',options('clients'),record?.clientId)+field('date','Fecha',record?.date||new Date().toISOString().slice(0,10),'date')+field('minutes','Duración (minutos)',record?.minutes||60,'number')+field('hourlyRate','Valor por hora',record?.hourlyRate||C.db().settings.hourlyTarget,'number')+textarea('description','Descripción',record?.description)},
 product:{entity:'inventoryProducts',title:'Producto',html:()=>field('name','Producto',record?.name,'text',true,'required')+field('sku','SKU interno',record?.sku)+selectField('category','Categoría',C.db().settings.inventoryCategories,record?.category)+field('stock','Existencia',record?.stock||0,'number')+field('minStock','Existencia mínima',record?.minStock||0,'number')+field('unitCost','Costo unitario',record?.unitCost||0,'number')+field('supplier','Proveedor',record?.supplier)+field('purchaseDate','Fecha de compra',record?.purchaseDate,'date')},
 movement:{entity:'inventoryMovements',title:'Movimiento de inventario',html:()=>selectField('productId','Producto',options('inventoryProducts'),record?.productId)+selectField('type','Tipo',['Entrada','Salida','Ajuste'],record?.type||'Salida')+field('quantity','Cantidad',Math.abs(record?.quantity||1),'number',false,'required min="1"')+selectField('projectId','Proyecto o asignación',options('projects'),record?.projectId)+field('date','Fecha',record?.date||new Date().toISOString().slice(0,10),'date')+textarea('notes','Notas',record?.notes)},
 followup:{entity:'followups',title:'Seguimiento',html:()=>selectField('clientId','Cliente',options('clients'),record?.clientId)+selectField('prospectId','Prospecto',options('prospects','businessName'),record?.prospectId)+selectField('projectId','Proyecto',options('projects'),record?.projectId)+field('date','Próxima fecha',record?.date||new Date().toISOString().slice(0,10),'date')+field('reason','Motivo',record?.reason,'text',true,'required')+selectField('channel','Canal',['WhatsApp','Llamada','Correo','Presencial','Otro'],record?.channel)+selectField('status','Estado',['Pendiente','Realizado'],record?.status||'Pendiente')+field('result','Resultado',record?.result)+textarea('notes','Notas',record?.notes)},
 service:{entity:'services',title:'Servicio',html:()=>field('name','Nombre',record?.name,'text',true,'required')+field('basePrice','Precio base',record?.basePrice||0,'number')+field('directCost','Costo directo',record?.directCost||0,'number')}
 };const f=O.formDefinition(kind,record||{})||forms[kind];if(!f)return;const dialog=$('#recordDialog');dialog.returnFocus=document.activeElement;$('#recordForm').dataset.kind=f.kind||kind;$('#recordForm').dataset.entity=f.entity;$('#recordForm').dataset.id=record?.id||'';$('#dialogSave').textContent='Guardar';$('#dialogSave').disabled=false;$('#dialogTitle').textContent=(record?.id?'Editar ':(kind==='quote'?'Nueva ':'Nuevo '))+f.title.toLowerCase();$('#dialogBody').innerHTML=`<div class="form-grid">${f.html()}</div>`;dialog.showModal();
 if(kind==='quote'){
   const recalcQuoteItems=()=>{const rows=[...String($('#f_deliverablesText')?.value||'').split(/\r?\n/),...String($('#f_extrasText')?.value||'').split(/\r?\n/)];const total=rows.reduce((sum,row)=>{const parts=row.split('|');return sum+(Number(parts[1])||1)*(Number(parts[2])||0)},0);if(total&&$('#f_price'))$('#f_price').value=total;updateQuoteCostPreview()};const packageSelect=$('#f_packageId');packageSelect.onchange=()=>{const pkg=C.get('packages',packageSelect.value);if(pkg){const values={price:pkg.price,deliverablesText:(pkg.contents||[pkg.name]).map((text,index)=>`${text} | 1 | ${index?0:pkg.price}`).join('\n'),estimatedHours:pkg.estimatedHours,hourlyValue:C.db().settings.hourlyTarget,stands:pkg.stands,nfcCards:pkg.nfcCards,trips:pkg.trips,software:pkg.software,providers:pkg.providers,otherCosts:pkg.otherCosts};Object.entries(values).forEach(([key,value])=>{const control=$(`#f_${key}`);if(control)control.value=value})}recalcQuoteItems()};$('#dialogBody').querySelectorAll('input,select,textarea').forEach(control=>control.addEventListener('input',control.id==='f_deliverablesText'||control.id==='f_extrasText'?recalcQuoteItems:updateQuoteCostPreview));updateQuoteCostPreview();
 }
}
function updateQuoteCostPreview(){const target=$('#quoteCostPreview');if(!target)return;const c=C.estimate({price:formNumber('price'),discount:formNumber('discount'),estimatedHours:formNumber('estimatedHours'),hourlyValue:formNumber('hourlyValue'),stands:formNumber('stands'),nfcCards:formNumber('nfcCards'),trips:formNumber('trips'),software:formNumber('software'),providers:formNumber('providers'),otherCosts:formNumber('otherCosts'),taxRate:formNumber('taxRate')});target.innerHTML=`<h3>Vista financiera antes de guardar</h3>${marginBadge(c.margin)}<div class="cost-stack"><span><small>Precio sin impuestos</small><b>${C.money(c.netPrice)}</b></span><span><small>Impuestos</small><b>${C.money(c.taxes)}</b></span><span><small>Costo directo</small><b>${C.money(c.directCost)}</b></span><span><small>Mano de obra</small><b>${C.money(c.labor)}</b></span><span><small>Costo económico</small><b>${C.money(c.economicCost)}</b></span><span><small>Utilidad</small><b>${C.money(c.profit)}</b></span></div>`}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function bindActions(){
  $$('[data-new]').forEach(b=>b.onclick=()=>openForm(b.dataset.new));$$('[data-edit]').forEach(b=>b.onclick=()=>{const[e,id]=b.dataset.edit.split(':');const map={prospects:'client',clients:'client',businesses:'client',packages:'package',quotes:'quote',projects:'project',payments:'financialMovement',expenses:'financialMovement',financialMovements:'financialMovement',timeEntries:'time',inventoryProducts:'product',followups:'followup',services:'service'};openForm(map[e],C.get(e,id))});
  $$('[data-archive]').forEach(b=>b.onclick=()=>{const[e,id]=b.dataset.archive.split(':');confirmAction('Archivar registro','El registro dejará de aparecer en las vistas activas.',()=>{C.archive(e,id);toast('Registro archivado.');render()})});
  $$('[data-mode]').forEach(b=>b.onclick=()=>{listMode=b.dataset.mode;render()});$$('[data-stage]').forEach(s=>s.onchange=()=>{C.upsert('prospects',{id:s.dataset.stage,stage:s.value});toast('Etapa actualizada.');render()});
  $$('[data-convert]').forEach(b=>b.onclick=()=>convertProspect(b.dataset.convert));$$('[data-project-from]').forEach(b=>b.onclick=()=>projectFromQuote(b.dataset.projectFrom));
  $$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-review]').forEach(b=>b.onclick=()=>showReview(b.dataset.review));$$('[data-download-review]').forEach(b=>b.onclick=()=>download(C.get('reviews',b.dataset.downloadReview).original,`${b.dataset.downloadReview}-revision-quio.json`));
  $$('[data-quote]').forEach(b=>b.onclick=()=>showQuote(b.dataset.quote));$$('[data-project]').forEach(b=>b.onclick=()=>showProject(b.dataset.project));
  $$('[data-done-followup]').forEach(b=>b.onclick=()=>{C.upsert('followups',{id:b.dataset.doneFollowup,status:'Realizado',completedAt:C.now()});toast('Seguimiento marcado como realizado.');render()});
  $$('[data-toggle-followup-archive]').forEach(b=>b.onclick=()=>{showArchivedFollowups=!showArchivedFollowups;render()});
  $$('[data-restore-followup]').forEach(b=>b.onclick=()=>{C.restore('followups',b.dataset.restoreFollowup);toast('Seguimiento restaurado.');render()});
  $$('[data-timer]').forEach(b=>b.onclick=()=>timerAction(b.dataset.timer));
  $$('[data-quote-package]').forEach(b=>b.onclick=()=>{const pkg=C.get('packages',b.dataset.quotePackage);openForm('quote',{packageId:pkg.id,items:[{description:pkg.name,quantity:1,price:pkg.price}],...pkg,id:null,status:'Borrador',taxRate:C.db().settings.taxRate})});
  $$('#simulator input,[id^="f_sim"]').forEach(input=>input.addEventListener('input',updateSimulator));
  $$('[id^="f_mix_"]').forEach(input=>input.addEventListener('input',updateProjection));
  $$('[data-scenario]').forEach(button=>button.onclick=()=>{const total=Number(button.dataset.scenario),packages=C.list('packages');packages.forEach((pkg,index)=>{const control=$(`#f_mix_${pkg.id}`);if(control)control.value=index===0?total:0});updateProjection()});
  const sf=$('#settingsForm');if(sf)sf.onsubmit=e=>{e.preventDefault();const values=formData(sf);['monthlyGoal','annualGoal','founderEmploymentIncome','totalMonthlyIncomeGoal','hourlyTarget','standUnitCost','nfcCardUnitCost','averageTripCost','healthyMargin','warningMargin','monthlyCapacityHours','taxRate'].forEach(key=>values[key]=Number(values[key]));Object.assign(C.db().settings,values);C.save();toast('Configuración guardada; paquetes y simuladores fueron recalculados.');render()};
  D.bindActions({render,toast,confirmAction});
  O.bindActions({render,toast,confirmAction,openForm});
}
function convertProspect(id){const p=C.get('prospects',id);if(!p)return;const existing=C.list('businesses').find(b=>b.name.toLowerCase()===p.businessName.toLowerCase());const b=existing||C.upsert('businesses',{name:p.businessName,industry:p.industry,phone:p.phone,email:p.email,status:'Activo',sourceProspectId:p.id},'biz');const c=C.upsert('clients',{name:p.contactName||`Contacto de ${p.businessName}`,phone:p.phone,email:p.email,businessIds:[b.id],status:'Activo',sourceProspectId:p.id},'cli');C.upsert('prospects',{id:p.id,stage:'Ganado',convertedClientId:c.id,convertedBusinessId:b.id});toast('Prospecto convertido sin duplicar información.');location.hash='#clients'}
function projectFromQuote(id){try{const p=D.projectFromQuote(id);toast('Proyecto creado y relacionado con la cotización.');location.hash='#projects';return p}catch(error){toast(error.message)}}
function confirmAction(title,text,fn){$('#confirmTitle').textContent=title;$('#confirmText').textContent=text;const d=$('#confirmDialog');d.returnFocus=document.activeElement;d.showModal();d.onclose=()=>{if(d.returnValue==='confirm')fn();d.returnFocus?.focus?.({preventScroll:true})}}
function action(name){
 if(name==='seed')return confirmAction('Cargar datos de demostración','Se reemplazarán los datos actuales por ejemplos claramente identificados.',()=>{C.seed();toast('Datos de ejemplo cargados.');render()});
 if(name==='import-review'){fileMode='review';$('#fileInput').click()}if(name==='backup')download({...C.db(),exportedAt:C.now()},`respaldo-quio-${new Date().toISOString().slice(0,10)}-v${C.SCHEMA}.json`);
 if(name==='restore'){fileMode='restore';$('#fileInput').click()}if(name==='merge'){fileMode='merge';$('#fileInput').click()}if(name==='csv')exportCSV();
 if(name==='reset')confirmAction('Eliminar todos los datos','Para confirmar, se solicitará escribir ELIMINAR. Esta acción crea antes una descarga de respaldo.',()=>{if(prompt('Escribe ELIMINAR para confirmar')!=='ELIMINAR')return;download(C.db(),`respaldo-previo-quio-${Date.now()}.json`);C.replace(C.emptyDB());toast('Datos eliminados; se descargó un respaldo previo.');render()});
 if(name==='clear-operational')confirmAction('Limpiar datos operativos de prueba','Se descargará un respaldo y se eliminarán todos los registros operativos sincronizados. La configuración, catálogos, paquetes, servicios e inventario base se conservarán.',()=>{if(prompt('Escribe ELIMINAR PRUEBAS para confirmar')!=='ELIMINAR PRUEBAS')return;const current=C.db(),next=C.emptyDB();download(current,`respaldo-previo-limpieza-quio-${Date.now()}.json`);next.settings=structuredClone(current.settings);next.services=structuredClone(current.services);next.packages=structuredClone(current.packages);next.inventoryProducts=structuredClone(current.inventoryProducts);next.meta={...next.meta,...current.meta,lastOperationalResetAt:C.now()};C.replace(next);toast('Datos operativos eliminados; configuración conservada.');render()});
 if(name==='compare')compareReviews();
}
let fileMode='review';$('#fileInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const json=JSON.parse(await file.text());if(fileMode==='review'){const rows=C.validateV50(json);pendingImport=rows;previewImport(rows)}else{if(!json.schemaVersion)throw new Error('El archivo no es un respaldo de Gestión Quio.');confirmAction(fileMode==='merge'?'Fusionar respaldo':'Restaurar respaldo',fileMode==='merge'?'Se conservarán los registros con IDs distintos y prevalecerá la versión más reciente.':'Se descargará una copia automática antes de reemplazar la base local.',()=>{if(fileMode==='merge')C.merge(json);else{download(C.db(),`respaldo-automatico-previo-${Date.now()}.json`);C.replace(json)}toast('Respaldo procesado correctamente.');render()})}}catch(err){toast(err.message||'No se pudo leer el archivo.')}};
function previewImport(rows){const r=rows[0],matches=C.list('businesses').filter(b=>b.name.toLowerCase()===r.business.name.toLowerCase());$('#recordForm').dataset.kind='review-import';$('#dialogTitle').textContent=`Importar ${rows.length} revisión(es)`;$('#dialogBody').innerHTML=`<div class="review-preview"><p class="eyebrow">VISTA PREVIA V50</p><h3>${esc(r.business.name)}</h3><div class="area-grid"><div class="area"><span>IQPD</span><strong>${r.iqpd}/100</strong></div>${Object.entries(r.pillars).map(([k,v])=>`<div class="area"><span>${esc(k)}</span><strong>${v??'No aplica'}</strong></div>`).join('')}</div></div><div class="form-grid" style="margin-top:14px">${selectField('businessId','Asociar con negocio',[{value:'',label:'Crear negocio desde la revisión'},...matches.map(x=>({value:x.id,label:x.name})),...C.list('businesses').filter(x=>!matches.includes(x)).map(x=>({value:x.id,label:x.name}))],matches[0]?.id||'')}</div>`;$('#recordDialog').showModal()}
$('#recordForm').addEventListener('submit',e=>{
 e.preventDefault();if(e.submitter?.value==='cancel'){e.currentTarget.closest('dialog').close();return}
 const submitButton=e.submitter;if(submitButton?.disabled)return;if(submitButton){submitButton.disabled=true;submitButton.dataset.label=submitButton.textContent;submitButton.textContent='Guardando…'}
 const kind=e.currentTarget.dataset.kind,data=formData(e.currentTarget);
 try{
   const special=D.handleSpecialForm(kind,data,e.currentTarget);
   if(special.handled){
     toast(kind==='document-acceptance'?'Aceptación registrada.':'Documento guardado correctamente.');
     if(special.keepOpen)return;
   }else if(kind==='review-import'){
     pendingImport.forEach(r=>{let businessId=data.businessId;if(!businessId){const b=C.upsert('businesses',{name:r.business.name,industry:r.business.otherType||r.business.type||'Sin registrar',city:r.business.city,address:r.business.address,mapsUrl:r.inventory?.profileUrl,websiteUrl:r.inventory?.websiteUrl,status:'Potencial',sourceReviewId:r.id},'biz');businessId=b.id}C.importReview(r,businessId)});
     pendingImport=null;toast('Revisión importada correctamente.');
   }else{
     const entity=e.currentTarget.dataset.entity,recordId=e.currentTarget.dataset.id;if(recordId)data.id=recordId;
     if(O.handleForm(kind,data,recordId))toast('Registro guardado correctamente.');
     else{
       ['amount','minutes','hourlyRate','stock','minStock','unitCost','basePrice','directCost','price','quantity','taxRate','discount','progress','estimatedHours','hourlyValue','stands','nfcCards','trips','software','providers','otherCosts'].forEach(key=>{if(key in data)data[key]=Number(data[key])});
       if(kind==='payment')data.includesTax=data.includesTax==='true';
       if(kind==='package')data.contents=String(data.contentsText||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
       if(kind==='quote')Object.assign(data,D.prepareQuote(data,recordId));
       if(kind==='movement'){
         const product=C.get('inventoryProducts',data.productId);let qty=Number(data.quantity);if(data.type==='Salida')qty=-qty;
         const resulting=Number(product?.stock||0)+qty;if(resulting<0&&!confirm(`La existencia quedará en ${resulting}. ¿Deseas continuar?`))return;
         data.quantity=qty;data.unitCostSnapshot=Number(product?.unitCost||0);if(product)C.upsert('inventoryProducts',{id:product.id,stock:resulting});
       }
       C.upsert(entity,data);toast('Registro guardado correctamente.');
     }
   }
   $('#recordDialog').close();render();
 }catch(error){toast(error.message)}finally{if(submitButton){submitButton.disabled=false;submitButton.textContent=submitButton.dataset.label||'Guardar'}}
});
function showReview(id){const r=C.get('reviews',id);$('#recordForm').dataset.kind='read-only';$('#dialogTitle').textContent='Revisión Quio';$('#dialogBody').innerHTML=`<div class="review-preview"><h3>${esc(biz(r.businessId)?.name||r.original.business.name)}</h3><p>${C.date(r.reviewDate)}</p><span class="score">${r.iqpd}</span>/100 · ${badge(r.level)}<h4>Resultado por área</h4><div class="area-grid">${Object.entries(r.pillars||{}).map(([k,v])=>`<div class="area"><span>${esc(k)}</span><strong>${v??'No aplica'}</strong></div>`).join('')}</div><h4>Recomendación</h4><p>${esc(r.recommendation?.name||'Sin recomendación')} — ${esc(r.recommendation?.reason||'')}</p><h4>Acciones propuestas</h4><ul>${(r.plan||[]).map(x=>`<li>${esc(x.text||x)}</li>`).join('')||'<li>Sin acciones registradas.</li>'}</ul></div>`;$('#recordDialog').showModal()}
function showQuote(id){D.showQuote(id);bindActions()}
function showProject(id){const project=C.get('projects',id),x=C.projectEconomics(id);$('#recordForm').dataset.kind='read-only';$('#dialogTitle').textContent=project.name;$('#dialogBody').innerHTML=`<div class="profit-comparison"><section><p class="eyebrow">ESTIMADO</p><h3>Lo acordado</h3><div class="cost-stack"><span><small>Precio sin impuestos</small><b>${C.money(x.agreedNet)}</b></span><span><small>Horas previstas</small><b>${x.estimatedHours.toFixed(1)} h</b></span><span><small>Mano de obra prevista</small><b>${C.money(x.estimatedLaborCost)}</b></span><span><small>Costos directos previstos</small><b>${C.money(x.estimatedDirectCost)}</b></span><span><small>Costo económico previsto</small><b>${C.money(x.estimatedEconomicCost)}</b></span><span><small>Utilidad prevista</small><b>${C.money(x.estimatedProfit)}</b></span><span><small>Margen previsto</small><b>${x.estimatedMargin.toFixed(1)}%</b></span></div>${marginBadge(x.estimatedMargin)}</section><section><p class="eyebrow">REAL</p><h3>Lo registrado hasta hoy</h3><div class="cost-stack"><span><small>Cobrado bruto</small><b>${C.money(x.collectedGross)}</b></span><span><small>Pendiente por cobrar</small><b>${C.money(x.pending)}</b></span><span><small>Horas reales</small><b>${x.actualHours.toFixed(1)} h</b></span><span><small>Mano de obra real</small><b>${C.money(x.actualLaborCost)}</b></span><span><small>Gastos reales</small><b>${C.money(x.actualExpenses)}</b></span><span><small>Materiales utilizados</small><b>${C.money(x.actualMaterials)}</b></span><span><small>Costo económico real</small><b>${C.money(x.actualEconomicCost)}</b></span><span><small>Utilidad económica real</small><b>${C.money(x.actualProfit)}</b></span><span><small>Margen real</small><b>${x.actualMargin.toFixed(1)}%</b></span><span><small>Flujo real</small><b>${C.money(x.flowReal)}</b></span></div>${marginBadge(x.actualMargin)}</section></div><article class="deviations"><p class="eyebrow">DESVIACIONES</p><div class="cost-stack"><span><small>Horas</small><b>${x.hourDeviation>=0?'+':''}${x.hourDeviation.toFixed(1)} h</b></span><span><small>Costos</small><b>${x.costDeviation>=0?'+':''}${C.money(x.costDeviation)}</b></span><span><small>Utilidad</small><b>${x.profitDeviation>=0?'+':''}${C.money(x.profitDeviation)}</b></span><span><small>Margen</small><b>${x.marginDeviation>=0?'+':''}${x.marginDeviation.toFixed(1)} pts</b></span></div></article><h3>Lista de verificación</h3>${(project.checklist||[]).map((item,index)=>`<label class="list-row"><input type="checkbox" data-check="${project.id}:${index}" ${item.done?'checked':''}><span>${esc(item.text)}</span></label>`).join('')||empty('Sin lista de verificación')}<p><strong>Próximo paso:</strong> ${esc(project.nextStep||'Sin registrar')}</p>`;$('#recordDialog').showModal();$$('[data-check]').forEach(c=>c.onchange=()=>{const[pid,index]=c.dataset.check.split(':');const stored=C.get('projects',pid);stored.checklist[index].done=c.checked;C.upsert('projects',stored);toast('Lista actualizada.')})}
function compareReviews(){const a=C.get('reviews',$('#compareA').value),b=C.get('reviews',$('#compareB').value),el=$('#comparison');if(a.businessId!==b.businessId){el.innerHTML='<div class="alert">Las revisiones deben pertenecer al mismo negocio.</div>';return}const delta=b.iqpd-a.iqpd;el.innerHTML=`<div class="compare-grid" style="margin-top:16px"><article class="review-preview"><p class="eyebrow">ANTES · ${C.date(a.reviewDate)}</p><span class="score">${a.iqpd}</span></article><article class="review-preview"><p class="eyebrow">AHORA · ${C.date(b.reviewDate)}</p><span class="score">${b.iqpd}</span><p class="delta">${delta>=0?'+':''}${delta} puntos</p></article></div><div class="area-grid" style="margin-top:12px">${Object.keys({...a.pillars,...b.pillars}).map(k=>`<div class="area"><span>${esc(k)}</span><strong>${a.pillars[k]??'—'} → ${b.pillars[k]??'—'}</strong><small>${a.pillars[k]!=null&&b.pillars[k]!=null?(b.pillars[k]-a.pillars[k]>=0?'+':'')+(b.pillars[k]-a.pillars[k]):'No comparable'}</small></div>`).join('')}</div><p class="muted">El cambio no se atribuye automáticamente a Quio. Registra por separado si fue acción de Quio, del cliente, un cambio externo o de origen no especificado.</p>`}
function timerAction(name){let t=timerState();if(name==='start'){if(!t)t={elapsed:0,description:'Registro del cronómetro',projectId:'',clientId:''};t.startedAt=Date.now();t.running=true;localStorage.setItem('quio_timer_v1',JSON.stringify(t));toast('Cronómetro iniciado. Puedes editar la descripción al detenerlo.')}if(name==='pause'&&t){t.elapsed=timerSeconds();t.running=false;delete t.startedAt;localStorage.setItem('quio_timer_v1',JSON.stringify(t));toast('Cronómetro en pausa.')}if(name==='stop'&&t){const seconds=timerSeconds();if(seconds>0)C.upsert('timeEntries',{date:new Date().toISOString().slice(0,10),minutes:Math.max(1,Math.round(seconds/60)),description:t.description||'Registro del cronómetro',projectId:t.projectId,clientId:t.clientId,hourlyRate:C.db().settings.hourlyTarget},'tim');localStorage.removeItem('quio_timer_v1');toast('Tiempo guardado.')}render()}
function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function exportCSV(){const rows=[['Tipo','ID','Nombre/Concepto','Estado','Fecha'],...C.ENTITIES.flatMap(e=>C.list(e).map(r=>[e,r.id,r.name||r.businessName||r.folio||r.description||r.reason||'',r.status||'',r.date||r.createdAt||'']))];const csv='\ufeff'+rows.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download=`tablas-quio-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function globalSearch(q){let box=$('.search-results');if(q.length<2){box?.remove();return}const hits=[];C.ENTITIES.forEach(e=>C.list(e).forEach(r=>{const text=JSON.stringify(r).toLowerCase();if(text.includes(q.toLowerCase()))hits.push({e,r})}));if(!box){box=document.createElement('div');box.className='search-results';box.setAttribute('role','listbox');document.body.appendChild(box)}box.innerHTML=hits.length?hits.slice(0,10).map(h=>`<a role="option" href="#${O.searchRoute(h.e)}"><strong>${esc(h.r.name||h.r.businessName||h.r.folio||h.r.reason||h.r.concept||h.r.description||h.e)}</strong><small class="muted"> ${esc(h.e)}</small></a>`).join(''):empty('Sin resultados','Prueba con otro término.')}
let globalSearchTimer;$('#globalSearch').addEventListener('input',e=>{clearTimeout(globalSearchTimer);const value=e.currentTarget.value;globalSearchTimer=setTimeout(()=>globalSearch(value),180)});$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){$('.search-results')?.remove();e.currentTarget.focus()}if(e.key==='ArrowDown'){e.preventDefault();$('.search-results a')?.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search,.search-results'))$('.search-results')?.remove()});$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#recordDialog').addEventListener('close',e=>{e.currentTarget.returnFocus?.focus?.({preventScroll:true})});window.addEventListener('hashchange',()=>{$('#sidebar').classList.remove('open');render()});window.addEventListener('quio:change',()=>{});window.QuioApp={render,openForm,convertProspect,projectFromQuote,compareReviews,timerAction,updateSimulator,updateProjection};render();
})();
